require("dotenv").config();
const fs = require("fs");
const path = require("path");
const puppeteer = require("puppeteer");
const readline = require("readline");
const axios = require("axios");
const FormData = require("form-data");
const rimraf = require("rimraf");

const IS_HEADLESS = "1" === process.env.HEADLESS || process.argv.includes("--headless");
const TELEGRAM_TOKEN = process.env.TELEGRAM_TOKEN;
const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;
const AKUN_FILE = path.join(__dirname, "AKUN.txt");
const PREMIUM_FILE = path.join(__dirname, "PREMIUM.txt");

const readAccounts = () => {
    try {
        return fs.readFileSync(AKUN_FILE, "utf-8")
            .split("\n")
            .filter(line => line.trim() && !line.trim().startsWith("//"))
            .map(line => {
                const parts = line.trim().split(" ");
                const email = parts[0];
                const pass = parts[1];
                return email && pass && email.includes("@") ? { email, pass, fullLine: line.trim() } : null;
            })
            .filter(account => account !== null);
    } catch (err) {
        return console.error("❌ Gagal membaca AKUN.txt:", err.message), [];
    }
};

const removeAccountFromFile = async (email) => {
    try {
        const remaining = fs.readFileSync(AKUN_FILE, "utf-8")
            .split("\n")
            .filter(line => !line.includes(email))
            .join("\n");
        fs.writeFileSync(AKUN_FILE, remaining);
        console.log(`🗑️ Akun ${email} dihapus dari AKUN.txt`);
    } catch (err) {
        console.error(`❌ Gagal menghapus akun ${email}:`, err.message);
    }
};

const savePremiumNew = async (email, pass) => {
    try {
        let lines = [];
        if (fs.existsSync(PREMIUM_FILE)) {
            lines = fs.readFileSync(PREMIUM_FILE, "utf-8").split("\n").filter(l => l.trim());
        }
        if (!lines.some(l => l.includes(email))) {
            lines.push(`${email} ${pass}`);
            fs.writeFileSync(PREMIUM_FILE, lines.join("\n") + "\n");
            console.log(`✅ [PREMIUM BARU] ${email} disimpan ke PREMIUM.txt`);
            await kirimTelegram(`✅ *Premium Berhasil:* \n\`${email}\``);
        }
        await removeAccountFromFile(email);
    } catch (err) {
        console.error("❌ Gagal simpan premium baru:", err.message);
    }
};

const savePremiumExisting = async (email, pass) => {
    try {
        let lines = [];
        if (fs.existsSync(PREMIUM_FILE)) {
            lines = fs.readFileSync(PREMIUM_FILE, "utf-8").split("\n").filter(l => l.trim());
        }
        if (!lines.some(l => l.includes(email))) {
            lines.push(`${email} ${pass} [ PREMIUM DULUAN ]`);
            fs.writeFileSync(PREMIUM_FILE, lines.join("\n") + "\n");
            console.log(`✅ [PREMIUM DULUAN] ${email} disimpan ke PREMIUM.txt`);
            await kirimTelegram(`🏅 *Sudah Premium:* \n\`${email}\``);
        }
        await removeAccountFromFile(email);
    } catch (err) {
        console.error("❌ Gagal simpan premium duluan:", err.message);
    }
};

const kirimTelegram = async (text) => {
    const url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage`;
    try {
        await axios.post(url, {
            chat_id: TELEGRAM_CHAT_ID,
            text: text,
            parse_mode: "Markdown"
        });
    } catch (err) {
        console.error("❌ Gagal kirim Telegram:", err.message);
    }
};

const kirimFileTelegram = async (filePath) => {
    const url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendDocument`;
    try {
        if (fs.statSync(filePath).size === 0) {
            return console.log(`⚠️ File ${path.basename(filePath)} kosong, tidak dikirim`);
        }
        const form = new FormData();
        form.append("chat_id", TELEGRAM_CHAT_ID);
        form.append("document", fs.createReadStream(filePath), {
            filename: path.basename(filePath),
            contentType: "text/plain"
        });
        const caption = filePath.includes("PREMIUM.txt") 
            ? "✅ *File PREMIUM.txt*\nBerisi akun-akun yang berhasil Premium" 
            : "📁 File hasil AutoPay";
        form.append("caption", caption);

        const res = await axios.post(url, form, { headers: form.getHeaders() });
        if (res.data.ok) {
            console.log(`✅ File ${path.basename(filePath)} berhasil dikirim ke Telegram`);
        }
    } catch (err) {
        console.error("❌ Error mengirim file:", err.message);
    }
};

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const askThreadCount = () => {
    // --- TAMBAHAN BYPASS UNTUK API ---
    // Jika script dijalankan dengan argumen --auto (dari receiver.js), 
    // langsung otomatis pakai 1 thread tanpa perlu input manual.
    if (process.argv.includes("--auto")) {
        console.log("🤖 Mode Auto terdeteksi! Menjalankan dengan 1 thread.");
        return Promise.resolve(1); 
    }
    // ---------------------------------

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });
    return new Promise(resolve => {
        rl.question("🧵 Mau pakai berapa thread (1-10)? ", answer => {
            rl.close();
            const count = parseInt(answer);
            if (isNaN(count) || count < 1 || count > 10) {
                console.log("❌ Input tidak valid. Masukkan angka 1 - 10.");
                process.exit(1);
            }
            resolve(count);
        });
    });
};

const loginToGoogle = async (email, pass, profilePath) => {
    let browser;
    try {
        browser = await puppeteer.launch({
            headless: IS_HEADLESS ? "new" : false,
            args: [
                "--user-data-dir=" + profilePath,
                "--no-sandbox",
                "--disable-setuid-sandbox",
                "--disable-dev-shm-usage",
                "--disable-web-security",
                "--disable-features=IsolateOrigins,site-per-process",
                "--ignore-certificate-errors",
                "--lang=en-US",
                "--disable-blink-features=AutomationControlled"
            ],
            defaultViewport: null,
            ignoreDefaultArgs: ["--enable-automation"]
        });

        const page = await browser.newPage();
        await page.setExtraHTTPHeaders({
            "Accept-Language": "en-US,en;q=0.9",
            "Upgrade-Insecure-Requests": "1"
        });

        await page.evaluateOnNewDocument(() => {
            Object.defineProperty(navigator, "webdriver", { get: () => false });
            Object.defineProperty(navigator, "plugins", { get: () => [1, 2, 3, 4, 5] });
            Object.defineProperty(navigator, "languages", { get: () => ["en-US", "en"] });
            window.chrome = { runtime: {} };
        });

        console.log(`\n[BROWSER] ${email}\n----------------------------------------------`);
        await page.goto("https://accounts.google.com/", { waitUntil: "networkidle2" });
        console.log("⏳ Proses Login...");
        await delay(2000);

        await page.type("input#identifierId", email, { delay: 100 });
        await page.evaluate(() => {
            const btn = Array.from(document.querySelectorAll("button")).find(b => {
                const span = b.querySelector("span");
                return span && "Next" === span.textContent.trim();
            });
            if (btn) btn.click();
        });

        await delay(5000);
        console.log("⏳ Menunggu element password siap...");
        await page.waitForSelector('input[name="Passwd"]', { timeout: 30000, visible: true });

        await page.type('input[name="Passwd"]', pass, { delay: 150 });
        await page.evaluate(() => {
            const btn = Array.from(document.querySelectorAll("button")).find(b => {
                const span = b.querySelector("span");
                return span && "Next" === span.textContent.trim();
            });
            if (btn) btn.click();
        });

        await delay(5000);
        let loginSuccess = false;
        for (let i = 0; i < 20; i++) {
            const currentUrl = page.url();
            if (currentUrl.includes("myaccount.google.com") || currentUrl.includes("accounts.google.com/signin/v2/challenge")) {
                loginSuccess = true;
                break;
            }
            await delay(1000);
        }

        if (loginSuccess) {
            console.log(`` + `✔ Akun ${email} berhasil login.`);
            return { success: true, browser, page, email, pass };
        } else {
            console.log(`✖ Akun ${email} gagal login.`);
            await browser.close();
            rimraf.sync(profilePath);
            return { success: false, email, pass };
        }
    } catch (err) {
        console.error(`✖ Error pada akun ${email}: ` + err.message);
        if (browser) await browser.close();
        rimraf.sync(profilePath);
        return { success: false, email, pass };
    }
};

const processYouTubeAutoPay = async ({ email, pass }, threadNum) => {
    const tempDir = path.join(__dirname, "TEMP");
    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });
    const profilePath = path.join(tempDir, `profile-${threadNum}-${Date.now()}`);

    console.log(`\n🔵 [${threadNum}] Memproses: ${email}`);
    const loginResult = await loginToGoogle(email, pass, profilePath);
    if (!loginResult.success) {
        return { email, success: false, reason: "LOGIN GAGAL" };
    }

    const { browser, page } = loginResult;
    try {
        console.log(`⏳ [${email}] Mengakses Youtube...`);
        await page.goto("https://music.youtube.com/youtube_premium/student", { waitUntil: "networkidle2" });
        await delay(3000);

        if (page.url().includes("/oops")) {
            console.log(`⚠️ [${email}] Redirect ke /oops - tidak dapat mengakses halaman student`);
            return { email, success: false, reason: "GAGAL OOPS" };
        }

        console.log(`⏳ [${email}] Mencari tombol pendaftaran...`);
        const isSignupBtnClicked = await page.evaluate(() => {
            const keywords = ["Lanjutkan dengan Mendaftar", "Continue With Signup", "Continue with Signup", "Lanjutkan", "Continue"];
            for (const btn of document.querySelectorAll("button")) {
                const txt = (btn.textContent || btn.getAttribute("aria-label") || "").trim();
                for (const kw of keywords) {
                    if (txt.includes(kw)) {
                        btn.click();
                        return true;
                    }
                }
            }
            return false;
        });

        if (!isSignupBtnClicked) {
            console.log(`⏳ [${email}] Tombol daftar tidak ada, cek status Premium Existing...`);
            await page.goto("https://music.youtube.com/paid_memberships", { waitUntil: "networkidle2" });
            await delay(3000);

            const checkPremium = await page.evaluate(() => {
                const tombolKelola = document.querySelector('button[aria-label="Kelola langganan"], button[aria-label="Manage subscription"], button[aria-label="Manage membership"]');
                if (tombolKelola) return true;
                for (const el of document.querySelectorAll("span.ytAttributedStringHost, yt-formatted-string#text")) {
                    const txt = el.textContent.trim();
                    if (txt.includes("Kelola langganan") || txt.includes("Manage subscription") || txt.includes("Manage membership")) return true;
                }
                return false;
            });

            if (checkPremium) {
                console.log(`🏅 [${email}] Sudah Premium duluan Bjirt`);
                await savePremiumExisting(email, pass);
                return { email, success: false, alreadyPremium: true };
            } else {
                console.log(`⚠ [${email}] Tombol daftar tidak ditemukan & bukan premium`);
                return { email, success: false, reason: "TOMBOL DAFTAR TIDAK DITEMUKAN" };
            }
        }

        console.log(`⏳ [${email}] Menunggu form pembayaran...`);
        await delay(5000);

        try {
            await page.waitForSelector("iframe#buyFlowDivIdIframe", { timeout: 10000 });
            const frame = await (await page.$("iframe#buyFlowDivIdIframe")).contentFrame();
            if (!frame) throw new Error("Iframe tidak dapat diakses");

            console.log(`` + `✔ [${email}] Berhasil mengakses iframe`);
            const isBuyClicked = await frame.evaluate(() => {
                const buyKeywords = ["Beli", "Buy"];
                for (const span of document.querySelectorAll("span.VfPpkd-vQzf8d")) {
                    if (buyKeywords.includes(span.textContent.trim())) {
                        const btn = span.closest("button");
                        if (btn) {
                            btn.click();
                            return true;
                        }
                    }
                }
                return false;
            });

            if (!isBuyClicked) {
                console.log(`⚠ [${email}] Tombol "Beli/Buy" tidak ditemukan`);
                return { email, success: false, reason: "TOMBOL BELI TIDAK DITEMUKAN" };
            }
            console.log(`✔ [${email}] Tombol "Beli/Buy" diklik`);
        } catch (err) {
            console.log(`⚠ [${email}] Error iframe: ` + err.message);
            return { email, success: false, reason: "IFRAME ERROR" };
        }

        console.log(`⏳ [${email}] Menunggu response transaksi...`);
        await delay(5000);

        let errorMsg = null;
        try {
            const frameElement = await page.$("iframe#buyFlowDivIdIframe");
            const frame = frameElement ? await frameElement.contentFrame() : null;
            if (frame) {
                errorMsg = await frame.evaluate(() => {
                    const selectors = ['div[id^="id-"][data-ur].n806', "div.d2Nfqe", 'div[jsname="Cjx5Nb"]', "div.LXRPh", 'span[jsslot] div[role="alert"]'];
                    for (const sel of selectors) {
                        const el = document.querySelector(sel);
                        if (el && el.textContent.trim().length > 0) return el.textContent.trim();
                    }
                    for (const el of document.querySelectorAll("div, span, p")) {
                        if (el.children.length > 3) continue;
                        const txt = el.textContent.trim();
                        if (txt.length > 0 && txt.length < 300) {
                            if (txt.includes("OR_FGVEM_21") || txt.includes("OR_PMCR_32") || txt.includes("Saldo rekening Anda") || txt.includes("Transaksi Anda tidak dapat diselesaikan")) {
                                return txt;
                            }
                        }
                    }
                    return null;
                });
            }
        } catch (err) {
            console.log(`⚠️ [${email}] Gagal cek error transaksi: ` + err.message);
        }

        if (errorMsg) {
            console.log(`📝 [${email}] Pesan error: ` + errorMsg);
            if (errorMsg.includes("Saldo rekening Anda") || errorMsg.includes("OR_FGVEM_21")) {
                console.log(`⚠️ [${email}] Saldo Gopay Kurang`);
                return { email, success: false, reason: "SALDO KURANG" };
            } else if (errorMsg.includes("Transaksi Anda tidak dapat diselesaikan") || errorMsg.includes("OR_PMCR_32")) {
                console.log(`🤖 [${email}] Transaksi ditolak`);
                return { email, success: false, reason: "DITOLAK" };
            } else {
                return { email, success: false, reason: "ERROR LAIN" };
            }
        }

        console.log(`⏳ [${email}] Menunggu dialog konfirmasi sukses...`);
        const successKeywords = [
            "Selamat datang", 
            "Welcome", 
            "YouTube Premium", 
            "YouTube Music", 
            "Tanda terima telah dikirimkan",
            "Terima kasih!",
            "Thank you"
        ];
        let isSuccess = false;
        try {
            await page.waitForFunction((kws) => {
                // Cek pada dialog konfirmasi biasa
                const titleEl = document.querySelector("yt-formatted-string#title.style-scope.yt-confirm-dialog-renderer, .yt-confirm-dialog-renderer #title");
                if (titleEl && kws.some(kw => titleEl.textContent.trim().includes(kw))) return true;

                // Cek juga pada seluruh teks halaman atau elemen yt-formatted-string yang mengandung kalimat tanda terima
                const allElements = document.querySelectorAll("yt-formatted-string, span, div");
                for (const el of allElements) {
                    const txt = el.textContent.trim();
                    if (kws.some(kw => txt.includes(kw))) {
                        return true;
                    }
                }
                return false;
            }, { timeout: 15000 }, successKeywords);
            isSuccess = true;
        } catch (e) {
            try {
                const frameElement = await page.$("iframe#buyFlowDivIdIframe");
                const frame = frameElement ? await frameElement.contentFrame() : null;
                if (frame) {
                    isSuccess = await frame.evaluate((kws) => {
                        const frameBody = document.body.textContent || "";
                        return kws.some(kw => frameBody.includes(kw));
                    }, successKeywords);
                }
            } catch (frameErr) {
                isSuccess = false;
            }
        }

        if (isSuccess) {
            console.log(`✅ [${email}] BERHASIL PAY TRIAL!.`);
            await savePremiumNew(email, pass);
            return { email, success: true, isPremium: true };
        } else {
            console.log(`⚠️ [${email}] Tidak ada error & tidak ada dialog sukses. Status abu-abu.`);
            return { email, success: false, reason: "STATUS TIDAK JELAS" };
        }

    } catch (err) {
        console.log(`🚫 Error akun ${email}: ` + err.message);
        return { email, success: false, reason: "ERROR" };
    } finally {
        try { if (browser) await browser.close(); } catch (e) {}
        try { if (fs.existsSync(profilePath)) rimraf.sync(profilePath); } catch (e) {}
    }
};

const processAccountsInBatches = async (accounts, threadCount) => {
    let batchIndex = 0;
    let successCount = 0;
    let existingPremiumCount = 0;
    let failedAccounts = [];

    while (accounts.length > 0) {
        console.log(`\n🚀 Batch ${batchIndex + 1}`);
        const currentBatch = accounts.splice(0, threadCount);

        const promises = currentBatch.map((account, index) => new Promise(resolve => {
            setTimeout(async () => {
                const res = await processYouTubeAutoPay(account, index + 1);
                if (res.isPremium) successCount++;
                else if (res.alreadyPremium) existingPremiumCount++;
                else failedAccounts.push({ email: account.email, reason: res.reason });
                resolve();
            }, 2000 * index);
        }));

        await Promise.all(promises);
        batchIndex++;
    }

    console.log("\n" + "=".repeat(50));
    console.log("📊 RINGKASAN YOUTUBE AUTO PAY");
    console.log("=".repeat(50));
    console.log(`✅ Premium Baru    : ${successCount} akun`);
    console.log(`✅ Sudah Premium   : ${existingPremiumCount} akun`);
    console.log(`❌ Gagal           : ${failedAccounts.length} akun`);

    if (failedAccounts.length > 0) {
        console.log("\n📋 Detail Akun Gagal:");
        failedAccounts.forEach((acc, i) => console.log(`  ${i + 1}. ${acc.email} - ${acc.reason || "Unknown"}`));
    }

    if (successCount > 0 && fs.existsSync(PREMIUM_FILE)) {
        await kirimFileTelegram(PREMIUM_FILE);
    }
    await kirimTelegram(`📊 *RINGKASAN YOUTUBE AUTO PAY*\n✅ Premium Baru: ${successCount}\n✅ Sudah Premium: ${existingPremiumCount}\n❌ Gagal: ${failedAccounts.length}`);
};

process.on("unhandledRejection", err => console.error("⚠️ Unhandled Rejection:", err));
process.on("uncaughtException", err => console.error("⚠️ Uncaught Exception:", err));

(async () => {
    console.log("\n" + "=".repeat(50));
    console.log("🎬 YOUTUBE AUTO PAY BOT");
    console.log("=".repeat(50));

    if (!fs.existsSync(AKUN_FILE)) fs.writeFileSync(AKUN_FILE, "");
    if (!fs.existsSync(PREMIUM_FILE)) fs.writeFileSync(PREMIUM_FILE, "");

    const tempDir = path.join(__dirname, "TEMP");
    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

    const accounts = readAccounts();
    if (accounts.length === 0) {
        console.log("❌ Tidak ada akun valid di AKUN.txt\n📝 Format: email@example.com password");
        process.exit(1);
    }

    console.log(`📋 Total ${accounts.length} akun akan diproses`);
    console.log(`🖥️ Headless mode: ${IS_HEADLESS ? "Ya" : "Tidak"}`);

    await kirimTelegram(`🚀 *Memulai YouTube Auto Pay*\nTotal akun: ${accounts.length}\nHeadless: ${IS_HEADLESS ? "Ya" : "Tidak"}`);
    const threads = await askThreadCount();

    await processAccountsInBatches(accounts, threads);

    if (fs.existsSync(tempDir)) {
        try { fs.rmSync(tempDir, { recursive: true, force: true }); console.log("🧹 Folder TEMP dibersihkan"); } catch (e) {}
    }
    console.log("\n✨ Semua proses selesai!");
})();
